import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse('{"title":"Language as Data and Runtime Split","description":"","frontmatter":{"title":"Language as Data and Runtime Split","type":"adr","date":"2026-09-02T00:00:00.000Z","status":"accepted","status_note":"Accepted — `Language` is serializable data; engines interpret it."},"headers":[],"relativePath":"handl/project/adrs/0044-language-as-data-and-runtime-split.md","filePath":"vendored/handl/project/adrs/0044-language-as-data-and-runtime-split.md"}'),a={name:`handl/project/adrs/0044-language-as-data-and-runtime-split.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="adr-0044-language-as-data-and-runtime-split" tabindex="-1">ADR-0044: Language as Data and Runtime Split <a class="header-anchor" href="#adr-0044-language-as-data-and-runtime-split" aria-label="Permalink to “ADR-0044: Language as Data and Runtime Split”">​</a></h1><h2 id="decision" tabindex="-1">Decision <a class="header-anchor" href="#decision" aria-label="Permalink to “Decision”">​</a></h2><ol><li><strong><code>Language</code> is pure serializable data</strong>, built by merging typed fragments (<code>Language::merge</code>, applied in kit-defined order).</li><li><strong>Staged entry points</strong>: each stage consumes only the previous stage&#39;s output plus the <code>Language</code>; <code>eval</code> takes an <code>Ast</code>, never <code>Source</code>.</li><li><strong>Crate structure</strong>: each <code>plugin-engine-*</code> stage splits into an abstraction crate (operation + trait) and an engine crate (interprets data).</li><li><strong>Evaluation schemes are data</strong> — the <code>eval</code> fragment set maps each <code>Ast</code> kind to a scheme; engines interpret it. Never closed machine instructions.</li><li><strong>Fragment merge distinguishes override from collision</strong> via <code>id</code> + <code>replaces: [id]</code>; no silent last-wins.</li><li><strong>Authored data files are canonical.</strong> Rust emitters are a temporary scaffold; if they stay, Rust remains the definition and self-hosting dies.</li><li><strong>Five review properties are required</strong>: composability (<code>requires</code>), extensibility, replaceability, performance, safety.</li></ol><h2 id="why" tabindex="-1">Why <a class="header-anchor" href="#why" aria-label="Permalink to “Why”">​</a></h2><p>The language was defined by Rust traits and emitters, so the definition could not be inspected, serialized or replaced. Self-hosting and multiple engines require the language to be data; silent last-wins merging made fragment composition unpredictable.</p><h2 id="not-doing" tabindex="-1">Not doing <a class="header-anchor" href="#not-doing" aria-label="Permalink to “Not doing”">​</a></h2><ul><li><strong>Keep Rust as the definition</strong> — emitters stay scaffold only.</li><li><strong>Silent last-wins merge</strong> — collisions are errors; overrides are declared.</li><li><strong>One crate per stage</strong> — abstraction and engine split.</li><li><strong>Hand-author all ~40 constructs on day one</strong> — emitters prove parity first.</li></ul><h2 id="consequences" tabindex="-1">Consequences <a class="header-anchor" href="#consequences" aria-label="Permalink to “Consequences”">​</a></h2><ul><li>Data files (<code>ast/grammar/eval/types/transforms</code>) become the review surface.</li><li>Emitters are deleted once parity is proven.</li><li>Engines are interchangeable behind the stage trait; kits select them.</li></ul><h2 id="enforcement" tabindex="-1">Enforcement <a class="header-anchor" href="#enforcement" aria-label="Permalink to “Enforcement”">​</a></h2><ul><li><code>kit-prelude-lang/crates/handl-kit-prelude-lang/data/</code> — the language data.</li><li><code>engine-*</code> — the abstraction/engine split.</li><li><code>handl-kit-data-*</code> — fragment types and merge.</li></ul><h2 id="design" tabindex="-1">Design <a class="header-anchor" href="#design" aria-label="Permalink to “Design”">​</a></h2><p>+Fragment shapes, merge rules, review refinements and the emitter migration: +<a href="./../design/0044-language-as-data-and-runtime-split.html"><code>design/0044-language-as-data-and-runtime-split.md</code></a>.</p>`,13)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};